{"path":"fees.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Investment — Fees & Offerings • {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfa;--ink:#1b1b1b;--muted:#60636a;--accent:#6b8f8f;--card:#ffffff}
    html,body{height:100%}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;line-height:1.45;color:var(--ink);background:linear-gradient(180deg,rgba(235,238,237,0.6),rgba(250,250,249,0.95));background-image:url('/assets/img/pattern.svg');background-attachment:fixed}
    .container{max-width:920px;margin:36px auto;padding:28px}
    header{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}
    nav a{color:var(--muted);text-decoration:none;margin:0 10px;font-weight:600;font-size:14px}
    .brand{font-weight:700;letter-spacing:0.2px}
    .hero{background:var(--card);padding:28px;border-radius:12px;box-shadow:0 6px 18px rgba(20,25,22,0.05)}
    h1{margin:0 0 6px;font-size:22px}
    p.lead{margin:0;color:var(--muted)}
    .grid{display:grid;grid-template-columns:1fr 300px;gap:18px;margin-top:20px}
    .card{background:var(--card);padding:18px;border-radius:10px}
    .price{font-weight:700;font-size:18px;color:var(--accent)}
    .pill{display:inline-block;padding:6px 10px;background:#eef6f5;border-radius:999px;color:#285a57;font-weight:700;margin-top:8px}
    ul{padding-left:18px}
    .small{font-size:13px;color:var(--muted)}
    footer{margin-top:28px;font-size:13px;color:var(--muted)}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;background:#1f6b63;color:#fff;border-radius:8px;text-decoration:none;font-weight:700}
    .muted-note{font-size:13px;color:var(--muted);margin-top:14px}
    @media(max-width:880px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div class="container">
    <header>
      <div class="brand">{{BUSINESS_NAME}}</div>
      <nav aria-label="Primary navigation">
        <a href="index.html">Start</a>
        <a href="about.html">Practice</a>
        <a href="specialties.html">Focus Areas</a>
        <a href="approach.html">Method</a>
        <a href="fees.html" aria-current="page">Investment</a>
        <a href="faq.html">Questions</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Connect</a>
      </nav>
    </header>

    <section class="hero" id="top">
      <h1>Fees & offerings — a clear way to choose what fits</h1>
      <p class="lead">Careful, time-limited options and ongoing sessions. Choose what best supports the concern you bring; we can adapt as work develops.</p>
      <p class="muted-note">Sessions are confidential clinical appointments. See scope & crisis note below.</p>
    </section>

    <div class="grid">
      <main>
        <div class="card">
          <h2 style="margin-top:0">How this practice frames services</h2>
          <p class="small">I offer focused short-term intensives, regular talk therapy sessions, and introductory bundles to orient care. Pricing is transparent and intended to reflect time, preparation, and clinical responsibility. Insurance may be used; contact for details.</p>

          <h3 style="margin-top:16px">Offerings</h3>

          <h4>Focused Intensive — Single deep session</h4>
          <div class="price">$260 — 90 minutes</div>
          <p class="small">A single extended appointment to work through a specific decision, transition, or preparation for a larger plan. Includes brief follow-up notes and one check-in message within 48 hours.</p>

          <h4 style="margin-top:12px">Stability Sessions — Ongoing care</h4>
          <div class="price">$160 — 50 minutes</div>
          <p class="small">Weekly or biweekly sessions to tend to patterns, skills, and steady progress. Best for sustained changes and building tools over time.</p>

          <h4 style="margin-top:12px">Starter Bridge — Short block</h4>
          <div class="price">3 sessions • $420 (prepaid)</div>
          <p class="small">A short, pre-paid package for people who want focused momentum without a long-term commitment. Sessions scheduled across 6–8 weeks.</p>

          <h4 style="margin-top:12px">Intensive Short Form — 4-week accelerator</h4>
          <div class="price">$900 — four sessions</div>
          <p class="small">A time-limited, structured set of meetings for concentrated work with suggested reflections between sessions.</p>

          <p style="margin-top:12px" class="small">Sliding scale may be available in limited cases. If cost is a barrier, please inquire — we can discuss what is possible without pressure.</p>

          <h3 style="margin-top:18px">Scheduling & policies</h3>
          <ul>
            <li class="small">Initial intake typically 50–60 minutes.</li>
            <li class="small">Late cancellation: please give 48 hours when possible; fees may apply.</li>
            <li class="small">Payment by card, online transfer, or invoiced arrangements for blocks.</li>
          </ul>

          <p class="muted-note">To reserve a time or ask about fit, use the Reserve link or reach out: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        </div>

        <div class="card" style="margin-top:18px">
          <h3>Confidentiality, scope, and urgent concerns</h3>
          <p class="small">Sessions are confidential within legal and ethical limits. I will explain boundaries of confidentiality and informed consent during first meetings. I do not provide emergency services. If you are in crisis or pose risk to yourself or others, contact local emergency services or crisis lines immediately.</p>
          <p class="small">I will work collaboratively with you and, with permission, coordinate care with outside providers when helpful. No promises or guarantees are made about outcomes.</p>
        </div>
      </main>

      <aside>
        <div class="card">
          <h3>Ready to talk about next steps?</h3>
          <p class="small">If you're unsure which option fits, I can help clarify during an initial conversation. Book a consult, or send a message with a brief note about your goals.</p>
          <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>

          <div style="margin-top:12px" class="small">
            <strong>Phone:</strong> {{PHONE}}<br>
            <strong>Email:</strong> <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>
          </div>

          <div style="margin-top:12px" class="pill">No insurance guarantees — ask about billing</div>
        </div>

        <div class="card" style="margin-top:16px">
          <h4 style="margin:0 0 8px 0">Helpful next steps</h4>
          <ol class="small">
            <li>Choose a service (intensive, ongoing, or starter).</li>
            <li>Reserve a time via Reserve page.</li>
            <li>Complete intake forms and bring any questions to your first session.</li>
          </ol>
        </div>
      </aside>
    </div>

    <footer>
      <p>Confidentiality note: Clinical records are kept as required by law and professional guidelines. Scope boundaries: sessions are therapeutic, not a substitute for emergency care or certain medical assessments. Crisis: if you are in danger or need immediate help, call local emergency services or a crisis line.</p>
      <p style="margin-top:6px">Questions about fees or insurance? Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call {{PHONE}}</p>
    </footer>
  </div>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Questions & Self-Screening • {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f7f8f7;--ink:#0f1a1a;--muted:#5d6166;--accent:#7a9a8f}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#fbfdfc,#f6f8f7);color:var(--ink)}
    .wrap{max-width:980px;margin:28px auto;padding:20px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{margin:0 9px;color:var(--muted);text-decoration:none;font-weight:600}
    h1{margin:8px 0}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:18px}
    .card{background:#fff;border-radius:10px;padding:18px;box-shadow:0 6px 18px rgba(18,24,22,0.04)}
    .faq q{font-style:italic}
    .small{font-size:13px;color:var(--muted)}
    button{background:var(--accent);color:#fff;padding:8px 12px;border-radius:8px;border:0;font-weight:700}
    .btn-ghost{background:transparent;border:1px solid #e6e9e7;color:var(--muted)}
    label{display:block;margin-top:10px;font-weight:700}
    input,select,textarea{width:100%;padding:8px;margin-top:6px;border-radius:8px;border:1px solid #e6e9e7}
    .result{white-space:pre-wrap;background:#f2f6f4;padding:12px;border-radius:8px;margin-top:10px;font-family:monospace;font-size:13px}
    @media(max-width:900px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div style="font-weight:700">{{BUSINESS_NAME}}</div>
      <nav aria-label="Main">
        <a href="index.html">Start</a>
        <a href="about.html">Practice</a>
        <a href="specialties.html">Focus Areas</a>
        <a href="approach.html">Method</a>
        <a href="fees.html">Investment</a>
        <a href="faq.html" aria-current="page">Questions</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Connect</a>
      </nav>
    </header>

    <h1>Questions, quick answers, and a self-check tool</h1>
    <p class="small">Below are common questions about sessions and a short, non-diagnostic self-screening wizard you can complete to prepare for a first meeting. It produces suggested talking points to bring to consultation.</p>

    <div class="grid" role="main">
      <main>
        <section class="card">
          <h2 style="margin-top:0">Frequently asked</h2>
          <div class="faq">
            <h3 style="margin-bottom:6px">How long are sessions?</h3>
            <p class="small">Typical sessions are 50 minutes. Intensives are longer as specified on the Investment page. We’ll discuss what length feels useful at intake.</p>

            <h3 style="margin-top:12px;margin-bottom:6px">Do you take insurance?</h3>
            <p class="small">Sometimes. If you plan to use insurance, let me know so we can discuss billing options and any necessary information.</p>

            <h3 style="margin-top:12px;margin-bottom:6px">What can I expect at the first appointment?</h3>
            <p class="small">We’ll review confidentiality, your goals, current concerns, and any prior treatment history that feels relevant. You can bring the self-screening summary created below to help focus the conversation.</p>
          </div>
        </section>

        <section class="card" style="margin-top:16px">
          <h2>Self-screening intake wizard</h2>
          <p class="small">This is a guided set of reflections to help you notice patterns and generate questions you'd like to bring to a consultation. It is not a diagnosis.</p>

          <form id="wizard" onsubmit="return false;">
            <label for="mainConcern">Main concern or reason you're seeking support</label>
            <input id="mainConcern" name="mainConcern" placeholder="e.g., feeling stuck at work, persistent worry" />

            <label for="duration">How long have you noticed this concern?</label>
            <select id="duration" name="duration">
              <option value="weeks">A few weeks</option>
              <option value="months">A few months</option>
              <option value="year">A year or more</option>
              <option value="variable">On and off over years</option>
            </select>

            <label for="impact">Which areas of life are affected? (check any)</label>
            <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px">
              <label class="small"><input type="checkbox" value="Mood" name="impact"> Mood</label>
              <label class="small"><input type="checkbox" value="Work" name="impact"> Work or school</label>
              <label class="small"><input type="checkbox" value="Relationships" name="impact"> Relationships</label>
              <label class="small"><input type="checkbox" value="Sleep" name="impact"> Sleep</label>
              <label class="small"><input type="checkbox" value="Health" name="impact"> Physical health</label>
            </div>

            <label for="goals">What would you like to be different? (1–2 short goals)</label>
            <input id="goals" name="goals" placeholder="e.g., feel less overwhelmed; improve communication" />

            <label for="concernsAboutTherapy">Any concerns about beginning therapy?</label>
            <input id="concernsAboutTherapy" name="concernsAboutTherapy" placeholder="e.g., worried about cost, unsure what to say" />

            <div style="margin-top:12px;display:flex;gap:8px">
              <button id="generate" onclick="generateNotes()">Create summary</button>
              <button class="btn-ghost" onclick="clearWizard()">Clear</button>
            </div>
          </form>

          <div id="wizardOutput" class="result" aria-live="polite" style="display:none"></div>
          <div style="margin-top:8px">
            <button id="copyWizard" style="display:none" onclick="copyWizard()">Copy summary</button>
          </div>

          <p class="small" style="margin-top:12px">Bring this summary to your first meeting if you like — it can help shape the first session efficiently.</p>
        </section>

      </main>

      <aside>
        <div class="card">
          <h3 style="margin-top:0">If you're unsure</h3>
          <p class="small">A brief phone or video consult can help decide which offering suits you. No pressure; it's a short conversation about fit and logistics.</p>
          <a class="small" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        </div>

        <div class="card" style="margin-top:12px">
          <h4 style="margin:0">Quick links</h4>
          <ul class="small">
            <li><a href="fees.html">Investment options</a></li>
            <li><a href="book.html">Reserve a time</a></li>
            <li><a href="contact.html">Contact</a></li>
          </ul>
        </div>

        <div class="card" style="margin-top:12px">
          <h4 style="margin:0">Safety & boundaries</h4>
          <p class="small">This wizard is not a clinical diagnosis. If you are experiencing an emergency or immediate risk, please contact emergency services or a crisis resource in {{CITY}}, {{STATE}}.</p>
        </div>
      </aside>
    </div>

    <footer style="margin-top:18px" class="small">
      Confidentiality: clinical notes are stored according to professional guidelines. I do not provide emergency services. For urgent help, contact local emergency services or crisis lines.
    </footer>
  </div>

  <script>
    function collectCheckboxes(name){
      const checks = Array.from(document.querySelectorAll('input[name="'+name+'"]:checked'));
      return checks.map(c=>c.value);
    }
    function generateNotes(){
      const main = document.getElementById('mainConcern').value.trim();
      const duration = document.getElementById('duration').value;
      const impact = collectCheckboxes('impact');
      const goals = document.getElementById('goals').value.trim();
      const concerns = document.getElementById('concernsAboutTherapy').value.trim();

      const durationText = ({weeks:'a few weeks',months:'a few months',year:'a year or more',variable:'variable/episodic'})[duration] || duration;

      let lines = [];
      lines.push('Self-check summary for initial consultation');
      lines.push('—');
      if(main) lines.push('Primary reason: ' + main);
      lines.push('Duration: ' + durationText);
      if(impact.length) lines.push('Areas affected: ' + impact.join(', '));
      if(goals) lines.push('Goals to bring to therapy: ' + goals);
      if(concerns) lines.push('Concerns about starting therapy: ' + concerns);

      lines.push('Questions to raise:');
      const suggestedQs = [];
      if(!main) suggestedQs.push('Can I describe how I noticed this issue?');
      if(impact.includes('Work')) suggestedQs.push('How might therapy support work-related stress or decisions?');
      if(impact.includes('Relationships')) suggestedQs.push('Could we look at communication patterns with important people?');
      if(goals) suggestedQs.push('How do we measure progress toward my goals?');
      suggestedQs.push('What is your approach to pacing and structure in sessions?');
      suggestedQs.push('How do you manage confidentiality and coordination of care?');
      suggestedQs.slice(0,6).forEach(q=>lines.push('- ' + q));

      const out = lines.join('\n');
      const oEl = document.getElementById('wizardOutput');
      oEl.style.display = 'block';
      oEl.textContent = out;
      document.getElementById('copyWizard').style.display = 'inline-block';
    }
    function copyWizard(){
      const text = document.getElementById('wizardOutput').textContent;
      navigator.clipboard && navigator.clipboard.writeText(text).then(()=>{
        const b = document.getElementById('copyWizard');
        const old = b.textContent;
        b.textContent = 'Copied';
        setTimeout(()=>b.textContent = old,1500);
      });
    }
    function clearWizard(){
      document.getElementById('wizard').reset();
      document.getElementById('wizardOutput').style.display='none';
      document.getElementById('copyWizard').style.display='none';
    }
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve • Book a session • {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#ffffff;--ink:#0d1a1a;--muted:#667071;--accent:#386b5e}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial;background:var(--bg);color:var(--ink)}
    .wrap{max-width:980px;margin:28px auto;padding:20px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none}
    h1{margin:6px 0}
    .row{display:flex;gap:18px}
    .col{flex:1}
    .card{background:#fff;padding:18px;border-radius:10px;box-shadow:0 8px 26px rgba(16,20,18,0.04)}
    label{display:block;margin-top:10px;font-weight:700}
    input,select,textarea{width:100%;padding:8px;margin-top:6px;border-radius:8px;border:1px solid #e8eeea}
    button{background:var(--accent);color:#fff;padding:10px 14px;border-radius:9px;border:0;font-weight:700}
    .small{font-size:13px;color:var(--muted)}
    .result{white-space:pre-wrap;background:#f3f6f5;padding:12px;border-radius:8px;margin-top:10px;font-family:monospace}
    .mini{font-size:13px;color:var(--muted);margin-top:10px}
    @media(max-width:880px){.row{flex-direction:column}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div style="font-weight:700">{{BUSINESS_NAME}}</div>
      <nav aria-label="Primary">
        <a href="index.html">Start</a>
        <a href="about.html">Practice</a>
        <a href="specialties.html">Focus Areas</a>
        <a href="approach.html">Method</a>
        <a href="fees.html">Investment</a>
        <a href="faq.html">Questions</a>
        <a href="book.html" aria-current="page">Reserve</a>
        <a href="contact.html">Connect</a>
      </nav>
    </header>

    <h1>Reserve a session</h1>
    <p class="small">Use the planner below to shape a session plan and then send a booking request. The planner creates a short, shareable summary for your records or to bring to the first meeting.</p>

    <div class="row">
      <div class="col card">
        <h2 style="margin-top:0">Session planner</h2>
        <p class="mini">A short interactive tool that recommends a format and generates a plain-text summary you can copy or paste into a message.</p>

        <label for="goal">Primary goal for therapy</label>
        <input id="goal" placeholder="e.g., manage anxiety, navigate a transition" />

        <label for="prefFreq">Preferred frequency</label>
        <select id="prefFreq">
          <option value="weekly">Weekly</option>
          <option value="biweekly">Biweekly</option>
          <option value="monthly">Monthly check-ins</option>
        </select>

        <label for="sessionLength">Session length</label>
        <select id="sessionLength">
          <option value="50">50 minutes</option>
          <option value="75">75 minutes</option>
          <option value="90">90 minutes (intensive)</option>
        </select>

        <label for="intensity">Preferred work pacing</label>
        <select id="intensity">
          <option value="gentle">Gentle, reflective</option>
          <option value="steady">Steady skill-building</option>
          <option value="focused">Intensive, short-term</option>
        </select>

        <label for="notes">Anything else to mention</label>
        <textarea id="notes" rows="4" placeholder="Context, scheduling constraints, prior therapy notes..."></textarea>

        <div style="margin-top:12px;display:flex;gap:8px">
          <button onclick="buildPlan()">Build plan</button>
          <button style="background:#e9eceb;color:var(--muted)" onclick="clearPlan()">Reset</button>
        </div>

        <div id="planOutput" class="result" style="display:none"></div>
        <div style="margin-top:10px">
          <button id="copyPlan" style="display:none" onclick="copyPlan()">Copy plan</button>
        </div>

        <p class="mini">When ready to request a booking, use the form on the right or follow the Reserve link to schedule directly.</p>
      </div>

      <div class="col card">
        <h2 style="margin-top:0">Booking request</h2>
        <p class="small">Fill this and I will respond about availability and fit.</p>
        <form id="bookForm" onsubmit="submitRequest(event)">
          <label for="name">Your name</label>
          <input id="name" required />

          <label for="email">Email</label>
          <input id="email" type="email" required placeholder="you@example.com" />

          <label for="phone">Phone</label>
          <input id="phone" placeholder="Optional" />

          <label for="preferred">Preferred times / timezone</label>
          <input id="preferred" placeholder="Mornings, afternoons, weekdays, timezone..." />

          <label for="message">Message or notes (paste planner summary here)</label>
          <textarea id="message" rows="6" placeholder="Paste the plan or write a short note"></textarea>

          <div style="margin-top:12px;display:flex;gap:8px">
            <button type="submit">Send request</button>
            <button type="button" style="background:#f3f5f4;color:var(--muted)" onclick="document.getElementById('bookForm').reset()">Clear</button>
          </div>

          <p class="small" style="margin-top:10px">By sending a request you consent to contacting you by email or phone about scheduling. You may withdraw consent at any time.</p>
        </form>

        <div style="margin-top:12px" class="small">Questions? Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call {{PHONE}}. Location: {{CITY}}, {{STATE}}</div>
      </div>
    </div>

    <footer style="margin-top:18px" class="small">
      Confidentiality & limits: Sessions are confidential except where disclosure is required by law. This service does not replace emergency or urgent care. If you are in crisis, please contact emergency services or local crisis resources immediately.
    </footer>
  </div>

  <script>
    function buildPlan(){
      const goal = document.getElementById('goal').value.trim();
      const freq = document.getElementById('prefFreq').value;
      const len = document.getElementById('sessionLength').value;
      const intensity = document.getElementById('intensity').value;
      const notes = document.getElementById('notes').value.trim();

      const freqText = ({weekly:'Weekly',biweekly:'Every two weeks',monthly:'Monthly check-ins'})[freq];
      const intensityMap = {gentle:'Reflective pace',steady:'Skill-building pace',focused:'Intensive short-term work'};

      const suggestedPackage = (len==='90' || intensity==='focused') ? 'Focused Intensive' : (freq==='weekly' ? 'Stability Sessions' : 'Starter Bridge');

      const lines = [];
      lines.push('Personalized session plan');
      lines.push('—');
      if(goal) lines.push('Goal: ' + goal);
      lines.push('Pacing: ' + (intensityMap[intensity] || intensity));
      lines.push('Suggested cadence: ' + freqText + ' • ' + len + ' min sessions');
      lines.push('Recommended option: ' + suggestedPackage);
      if(notes) { lines.push('Notes: ' + notes); }
      lines.push('Next steps: Book an initial intake; bring this summary and any questions about approach or logistics.');

      const out = lines.join('\n');
      const el = document.getElementById('planOutput');
      el.style.display = 'block';
      el.textContent = out;
      document.getElementById('copyPlan').style.display = 'inline-block';
    }
    function copyPlan(){
      const text = document.getElementById('planOutput').textContent;
      navigator.clipboard && navigator.clipboard.writeText(text).then(()=>{
        const b = document.getElementById('copyPlan');
        const old = b.textContent;
        b.textContent = 'Copied';
        setTimeout(()=>b.textContent = old,1200);
      });
    }
    function clearPlan(){
      document.getElementById('goal').value = '';
      document.getElementById('prefFreq').selectedIndex = 0;
      document.getElementById('sessionLength').selectedIndex = 0;
      document.getElementById('intensity').selectedIndex = 0;
      document.getElementById('notes').value = '';
      document.getElementById('planOutput').style.display = 'none';
      document.getElementById('copyPlan').style.display = 'none';
    }

    function submitRequest(e){
      e.preventDefault();
      const payload = {
        name:document.getElementById('name').value.trim(),
